final class Order
{
    private array $items = [];

    public function add(string $sku): void
    {
        $this->items[$sku] = true;
    }

    public function count(): int
    {
        return count($this->items);
    }

    public function remove(string $sku): void
    {
        if (count($this->items) === 1) {
            throw new DomainException('last item');
        }
        unset($this->items[$sku]);
    }
}
